 * @param nextLineTabStop The number of spaces to pad subsequent lines with.
 * @param text The text to render.
 *
 * @return The (possibly new) StringBuffer with the rendered text.
 */
protected StringBuffer renderWrappedText(StringBuffer sb, int width, 
                                             int nextLineTabStop, String text)
    {
        // 1. Robustness: Handle null or empty input gracefully.
        if (text == null || text.isEmpty()) {
            return sb;
        }

        // 2. Robustness: Validate dimensional parameters to prevent exceptions/infinite loops.
        if (width <= 0) {
            // Cannot wrap to a non-positive width, return buffer as-is.
            return sb;
        }
        if (nextLineTabStop >= width) {
            // Hanging indent cannot be >= width, this would lead to infinite loops.
            throw new IllegalArgumentException("nextLineTabStop must be less than width.");
        }

        String remainingText = text;
        final String padding = createPadding(nextLineTabStop);
        boolean firstLine = true;

        // 3. Refactored Logic: Process the text in a single, clear loop.
        while (remainingText.length() > 0) {
