import java.io.ObjectInputStream;
import java.io.ObjectStreamClass;
import java.lang.reflect.Field;
import java.lang.reflect.Method;

/**
 * An abstract class that provides a mechanism to create object instances without invoking their constructors.
 * This is used internally by serialization libraries to handle classes without no-arg constructors.
 *
 * This is a placeholder for the full class definition. The key change is in the static
 * initialization logic shown below.
 */
public abstract class UnsafeAllocator {

  public abstract <T> T newInstance(Class<T> c) throws Exception;

  /**
   * A cached, singleton instance of the UnsafeAllocator.
   * Its initialization is deferred to a private static method that probes the runtime.
   */
  private static final UnsafeAllocator INSTANCE = initialize();

  /**
   * Returns a globally shared instance of {@code UnsafeAllocator}. This instance is
   * created once and cached, making subsequent calls highly efficient.
   */
  public static UnsafeAllocator create() {
    return INSTANCE;
  }

  /**
   * Probes the runtime environment to find a suitable mechanism for unsafe allocation.
   * This method is executed only once when the class is loaded.
   *
   * @return A functional UnsafeAllocator for the current platform.
   */
  private static UnsafeAllocator initialize() {
    // Strategy 1: Try the standard JVM's sun.misc.Unsafe
    try {
      Class<?> unsafeClass = Class.forName("sun.misc.Unsafe");
      Field f = unsafeClass.getDeclaredField("theUnsafe");
      f.setAccessible(true);
      final Object unsafe = f.get(null);
      final Method allocateInstance = unsafeClass.getMethod("allocateInstance", Class.class);
      return new UnsafeAllocator() {
        @Override
        @SuppressWarnings("unchecked")
        public <T> T newInstance(Class<T> c) throws Exception {
          if (c == null) {
            throw new IllegalArgumentException("Class to instantiate must not be null");
          }
          return (T) allocateInstance.invoke(unsafe, c);
        }
      };
    } catch (Exception e) {
      // This mechanism is not available. In a real application, log this at a DEBUG level.
      // For example: log.debug("sun.misc.Unsafe is not available.", e);
    }

    // Strategy 2: Try Android's Dalvik/ART runtime (post-Gingerbread)
    try {
      Method getConstructorId = ObjectStreamClass.class
          .getDeclaredMethod("getConstructorId", Class.class);
      getConstructorId.setAccessible(true);
      final int constructorId = (Integer) getConstructorId.invoke(null, Object.class);
      final Method newInstance = ObjectStreamClass.class
          .getDeclaredMethod("newInstance", Class.class, int.class);
      newInstance.setAccessible(true);
      return new UnsafeAllocator() {
        @Override
        @SuppressWarnings("unchecked")
        public <T> T newInstance(Class<T> c) throws Exception {
          if (c == null) {
            throw new IllegalArgumentException("Class to instantiate must not be null");
          }
          return (T) newInstance.invoke(null, c, constructorId);
        }
      };
    } catch (Exception e) {
      // This mechanism is not available. In a real application, log this at a DEBUG level.
    }

    // Strategy 3: Try older Android Dalvik runtime (pre-Gingerbread)
    try {
      final Method newInstance = ObjectInputStream.class
          .getDeclaredMethod("newInstance", Class.class, Class.class);
      newInstance.setAccessible(true);
      return new UnsafeAllocator() {
        @Override
        @SuppressWarnings("unchecked")
        public <T> T newInstance(Class<T> c) throws Exception {
          if (c == null) {
            throw new IllegalArgumentException("Class to instantiate must not be null");
          }
          return (T) newInstance.invoke(null, c, Object.class);
        }
      };
    } catch (Exception e) {
      // This mechanism is not available. In a real application, log this at a DEBUG level.
    }

    // Strategy 4: Give up
    return new UnsafeAllocator() {
      @Override
      public <T> T newInstance(Class<T> c) {
        throw new UnsupportedOperationException("Cannot allocate " + c + ". Your platform lacks a mechanism "
            + "to create instances without invoking constructors. This is often required for deserialization "
            + "of classes without a no-arg constructor.");
      }
    };
  }
}
