/**
 * A corrected, robust implementation of the StringUtils.equals method.
 */
public static boolean equals(CharSequence cs1, CharSequence cs2) {
    // 1. Identity check: if they are the same object, they are equal.
    // This also correctly handles the case where both are null.
    if (cs1 == cs2) {
        return true;
    }

    // 2. Null check: if we reach here, they are not the same object.
    // If either is null, they can't be equal.
    if (cs1 == null || cs2 == null) {
        return false;
    }

    // 3. Length check: if lengths differ, they can't be equal.
    // This is a critical and efficient short-circuit.
    if (cs1.length() != cs2.length()) {
        return false;
    }

    // 4. Optimization for the common String case, which is highly optimized.
    if (cs1 instanceof String && cs2 instanceof String) {
        return cs1.equals(cs2);
    }

    // 5. Fallback to a character-by-character comparison for all other
    // CharSequence types (e.g., StringBuilder, StringBuffer, CharBuffer).
    final int length = cs1.length();
    for (int i = 0; i < length; i++) {
        if (cs1.charAt(i) != cs2.charAt(i)) {
            return false;
        }
    }

    return true;
}
